+	// is true: colour codes, spinners, in-place updates. The parsers already
+	// strip ANSI in some cases (codex) but defending up-front keeps every
+	// agent's event stream clean.
+	cmd.Env = appendNoDecorationEnv(cmd.Env)
+	return &ptyReader{r: ptmx}, ptmx, tty, nil
+}
+
+func closePTY(ptmx, tty *os.File) {
+	if tty != nil {
+		_ = tty.Close()
+	}
+	if ptmx != nil {
+		_ = ptmx.Close()
+	}
