+func isEIO(err error) bool {
+	if errors.Is(err, syscall.EIO) {
+		return true
+	}
+	var pathErr *os.PathError
+	if errors.As(err, &pathErr) {
+		return errors.Is(pathErr.Err, syscall.EIO)
+	}
+	return false
+}
