+// TestParseClaudeOutput_StreamsPerLine pins the line-by-line streaming
+// contract: each newline-terminated write to the parser's input must surface
+// as an event before the next line is written. Documents that the bufio.Scanner
+// parser is NOT the bottleneck when events arrive batched in real reviews —
+// any batching must come from upstream (the agent process buffering its own
+// stdout when it detects a pipe instead of a TTY).
+func TestParseClaudeOutput_StreamsPerLine(t *testing.T) {
+	t.Parallel()
+
+	pr, pw := io.Pipe()
+	events := parseClaudeOutput(pr)
+
+	// Drain Started.
+	select {
+	case ev := <-events:
+		if _, ok := ev.(reviewtypes.Started); !ok {
+			t.Fatalf("first event = %T, want Started", ev)
+		}
+	case <-time.After(2 * time.Second):
+		t.Fatal("timed out waiting for Started")
+	}
+
+	writeAndExpect := func(line, wantText string) {
+		t.Helper()
+		if _, err := pw.Write([]byte(line + "\n")); err != nil {
+			t.Fatalf("pipe write: %v", err)
+		}
+		select {
+		case ev := <-events:
+			at, ok := ev.(reviewtypes.AssistantText)
+			if !ok {
+				t.Fatalf("event = %T, want AssistantText", ev)
+			}
+			if at.Text != wantText {
+				t.Fatalf("AssistantText.Text = %q, want %q", at.Text, wantText)
+			}
+		case <-time.After(2 * time.Second):
+			t.Fatalf("timed out waiting for AssistantText{Text: %q} — parser buffered instead of streaming", wantText)
+		}
+	}
+
+	writeAndExpect("first line", "first line")
+	writeAndExpect("second line", "second line")
+	writeAndExpect("third line", "third line")
+
+	_ = pw.Close()
+
+	// Final Finished event after EOF.
