+	case ev := <-events:
+		fin, ok := ev.(reviewtypes.Finished)
+		if !ok {
+			t.Fatalf("final event = %T, want Finished", ev)
+		}
+		if !fin.Success {
+			t.Error("Finished.Success = false, want true on clean EOF")
+		}
